import type { MetadataRoute } from "next";

// PWA manifest — served at /manifest.webmanifest. Icons are generated by
// scripts/gen-pwa-icons.py from the clay db mark; colors match the shell
// (zinc-950 surfaces, emerald accent) so the splash and the app blend.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "SeeQL — stop memorizing SQL. Start seeing it.",
    short_name: "SeeQL",
    description:
      "A visual SQL learning lab: animated diagrams for every hard idea, live-graded queries on a real SQLite storefront, quiz questions with instant feedback, and XP-driven progress.",
    id: "/",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#09090b",
    theme_color: "#09090b",
    categories: ["education", "productivity"],
    icons: [
      { src: "/icons/pwa-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/pwa-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icons/pwa-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
